        <!-- 装饰性玫瑰 -->
        <div class="floating-rose rose-1">
            <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
                <path d="M50,20 C60,10 80,15 80,30 C80,45 65,50 50,40 C35,50 20,45 20,30 C20,15 40,10 50,20 Z" fill="#f43f82"/>
                <path d="M50,25 C57,18 70,21 70,30 C70,39 60,43 50,37 C40,43 30,39 30,30 C30,21 43,18 50,25 Z" fill="#f59e0b"/>
            </svg>
        </div>
        <div class="floating-rose rose-2">
            <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
                <path d="M50,20 C60,10 80,15 80,30 C80,45 65,50 50,40 C35,50 20,45 20,30 C20,15 40,10 50,20 Z" fill="#f43f82"/>
                <path d="M50,25 C57,18 70,21 70,30 C70,39 60,43 50,37 C40,43 30,39 30,30 C30,21 43,18 50,25 Z" fill="#f59e0b"/>
            </svg>
        </div>

        <div class="main-card rounded-lg shadow-lg overflow-hidden">
            <!-- 装饰角 -->
            <div class="decorative-corner corner-tl"></div>
            <div class="decorative-corner corner-tr"></div>
            <div class="decorative-corner corner-bl"></div>
            <div class="decorative-corner corner-br"></div>

            <!-- 顶部信息栏 -->
            <div class="px-4 py-3 header-bar flex justify-between items-center">
                <div class="flex items-center gap-4 text-rose-light">
                    <span id="day-display" class="flex items-center"><i class="fa fa-calendar rose-icon mr-2"></i> 加载中...</span>
                    <span id="location-display" class="flex items-center"><i class="fa fa-map-marker rose-icon mr-2"></i> 加载中...</span>
                </div>
                <div id="timephase-display" class="font-bold gold-text flex items-center">
                    <i class="fa fa-clock-o gold-icon mr-2"></i>
                    <span></span>
                </div>
            </div>

            <!-- 标签页导航 -->
            <nav class="border-b border-rose-border flex">
                <button class="tab-btn active" data-tab="player"><i class="fa fa-user-circle mr-2 gold-icon"></i> <span class="font-decorative">{{user}}</span></button>
                <button class="tab-btn" data-tab="brides"><i class="fa fa-heart mr-2 rose-icon"></i> <span class="font-decorative">新娘</span></button>
                <button class="tab-btn" data-tab="villa"><i class="fa fa-home mr-2 gold-icon"></i> <span class="font-decorative">别墅</span></button>
            </nav>

            <!-- 标签页内容 -->
            <div id="tabs-content" class="min-h-[200px] relative z-10">
                <!-- 玩家状态 -->
                <div id="player-tab" class="tab-content active"></div>
                <!-- 新娘列表 -->
                <div id="brides-tab" class="tab-content p-4"></div>
                <!-- 别墅信息 -->
                <div id="villa-tab" class="tab-content p-4"></div>
