    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const dataElement = document.getElementById('yaml-data-source');
            if (!dataElement.textContent.trim()) return;

            try {
                const yamlData = jsyaml.load(dataElement.textContent);
                const gameStatus = yamlData.GameStatus || {};

                renderHeader(gameStatus);
                setupTabs(gameStatus);
                renderOptions(gameStatus.ActionOptions || {});

                // 事件委托处理选项点击
                document.getElementById('options-list').addEventListener('click', (e) => {
                    const target = e.target.closest('.option-item');
                    if(target) {
                        const cleanText = target.textContent.trim().replace(/^\d+\.\s*/, '').replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();
                        if (typeof triggerSlash === 'function') {
                            triggerSlash(`/setinput ${cleanText}`);
                        } else {
                            console.log('Would set input:', cleanText);
                        }
                    }
                });

            } catch (error) {
                console.error('状态栏渲染失败:', error);
                document.getElementById('tabs-content').innerHTML = `<div class="p-4 text-red-400">渲染错误: ${error.message}</div>`;
            }
        });

        function renderHeader(data) {
            document.getElementById('day-display').innerHTML = `<i class="fa fa-calendar rose-icon mr-2"></i> ${data.Day || '未知日期'}`;
            document.getElementById('location-display').innerHTML = `<i class="fa fa-map-marker rose-icon mr-2"></i> ${data.Location || '未知地点'}`;
            document.getElementById('timephase-display').innerHTML = `<i class="fa fa-clock-o gold-icon mr-2"></i> ${data.TimePhase || ''}`;
        }

        function setupTabs(data) {
            const tabButtons = document.querySelectorAll('.tab-btn');
            const tabContents = document.querySelectorAll('.tab-content');

            renderPlayerTab(data.Player || {});
            renderBridesTab(data.Brides || []);
            renderVillaTab(data.Villa || {});

            tabButtons.forEach(button => {
                button.addEventListener('click', () => {
                    tabButtons.forEach(btn => btn.classList.remove('active'));
                    tabContents.forEach(content => content.classList.remove('active'));

                    button.classList.add('active');
                    document.getElementById(`${button.dataset.tab}-tab`).classList.add('active');
                });
            });
        }

        function createInfoGrid(data) {
            let html = '<div class="info-grid">';
            for(const [key, value] of Object.entries(data)) {
                 if(typeof value === 'object' && value !== null) {
                    html += `<div class="sm:col-span-2 mt-2">
                                <strong class="text-rose-primary section-title">${key}</strong>
                                <div class="pl-4 mt-2 space-y-2 border-l border-rose-border/50">`
                    for (const [subKey, subValue] of Object.entries(value)) {
                         html += `<div><span class="gold-text">${subKey}:</span> <span class="text-rose-light">${subValue}</span></div>`;
                    }
                    html += `</div></div>`
                 } else if (Array.isArray(value)) {
                    html += `<div class="sm:col-span-2 mt-2">
                                <strong class="text-rose-primary section-title">${key}</strong>
                                <div class="pl-4 mt-2 text-rose-light">${value.join(', ')}</div>
                             </div>`;
                 }
                 else {
                    html += `<div><strong class="gold-text">${key}:</strong> <span class="text-rose-light">${value}</span></div>`;
                }
            }
            html += '</div>';
            return html;
        }

        function renderPlayerTab(playerData) {
            document.getElementById('player-tab').innerHTML = `
                <div class="p-4">
                    <h3 class="text-rose-gold text-lg font-decorative mb-4 section-title">玩家状态</h3>
                    ${createInfoGrid(playerData)}
                </div>
            `;
        }

        function renderBridesTab(bridesData) {
            const container = document.getElementById('brides-tab');
            if (bridesData.length === 0) {
                container.innerHTML = '<p class="text-rose-light/70 text-center py-8 italic"><i class="fa fa-heart-broken rose-icon mr-2"></i>还没有迎娶任何新娘...</p>';
                return;
            }
            let html = '<div class="space-y-4">';
            html += '<h3 class="text-rose-gold text-lg font-decorative mb-4 section-title">新娘列表</h3>';
            bridesData.forEach(bride => {
                html += `<div class="bride-card p-4">
                            <h4 class="font-bold text-rose-primary text-lg mb-3 font-decorative">${bride['名字']}</h4>
                            ${createInfoGrid({
                                '等级': bride['等级'],
                                '颜值': bride['颜值'],
                                '危险程度': bride['危险程度'],
                                '当前行动': bride['当前行动'],
                                '内心想法': `<span class="italic text-rose-light/80">"${bride['内心想法'] || '...'}"</span>`
                            })}
                        </div>`;
            });
            html += '</div>';
            container.innerHTML = html;
        }

        function renderVillaTab(villaData) {
            let html = `<div>
                <h3 class="text-rose-gold text-lg font-decorative mb-4 section-title">别墅信息</h3>
                <p class="text-sm mb-4"><strong class="gold-text">别墅等级:</strong> <span class="text-rose-light">${villaData['等级'] || 'N/A'}</span></p>
                <h4 class="font-bold text-rose-primary mb-3 font-decorative section-title">设施状态</h4>
                <ul class="space-y-3 text-sm">`;

            // 修复设施显示问题 - 直接遍历设施对象
            if(villaData.设施 && typeof villaData.设施 === 'object') {
                for (const [facility, status] of Object.entries(villaData.设施)) {
                    const isOpen = status.includes('✅');
                    html += `<li class="flex items-center">
                                <i class="fa ${isOpen ? 'fa-check-circle text-facility-open' : 'fa-times-circle text-facility-closed'} w-5 mr-2"></i>
                                <span class="${isOpen ? 'text-rose-light' : 'text-rose-light/50'}">${facility}: ${status.replace(/[✅❌]/g, '').trim()}</span>
                             </li>`;
                }
            } else {
                html += '<li class="text-rose-light/50">暂无设施信息</li>';
            }

            html += `</ul></div>`;
            document.getElementById('villa-tab').innerHTML = html;
        }

        function renderOptions(optionsData) {
            document.getElementById('action-owner').textContent = optionsData.Owner || '你';
            const list = document.getElementById('options-list');
            list.innerHTML = '';
            if (!optionsData.Options || optionsData.Options.length === 0) {
                 list.innerHTML = '<li class="text-rose-light/50"><i class="fa fa-exclamation-circle mr-2"></i>当前无可用选项</li>';
                 return;
            }
            optionsData.Options.forEach((option, index) => {
                const li = document.createElement('li');
                li.className = 'option-item';
                li.innerHTML = `<span class="number gold-text mr-2">${index + 1}.</span> ${option}`;
                list.appendChild(li);
            });
        }
    </script>
</body>
</html>
